const wrRb = [{"criterion":"Inhalt","description":"Vollständigkeit und Relevanz der Informationen","points":5,"key":"content"},{"criterion":"Grammatik","description":"Korrektheit von Satzstruktur, Verbposition, Artikeln und Zeitformen","points":5,"key":"grammar"},{"criterion":"Wortschatz","description":"Angemessene und abwechslungsreiche Wortwahl auf A2-Niveau","points":5,"key":"vocabulary"},{"criterion":"Kohärenz","description":"Logischer Aufbau, Verbindungssätze, nachvollziehbare Reihenfolge","points":5,"key":"coherence"}]
