console.log("\n=== STEP 2: Enrich A2 Lessons ===\n");
const a2l = d.lessons.filter(x=>x.id&&x.id.startsWith("A2_"));
a2l.forEach(l=>{
  l.conceptId = lcid[l.id];
  l.estimatedMinutes = l.estimatedMinutes || (l.id==="A2_lesson_25"?60:50);
  l.prerequisiteConceptIds = lpr[l.id] || [];
  l.conceptsTaught = lct[l.id] || [];
  l.commonMistakes = l.commonMistakes && l.commonMistakes.length ? l.commonMistakes : lcm[l.id] || [];
  l.formsTable = l.formsTable && l.formsTable.length ? l.formsTable : lft[l.id] || [];
  l.miniDrills = l.miniDrills && l.miniDrills.length ? l.miniDrills : lmd[l.id] || [];
  l.trackTags = l.trackTags && l.trackTags.length ? l.trackTags : ltt[l.id] || [];
  l.lessonDepthVersion = "2.0";
  if(!l.linkedQuestionIds) l.linkedQuestionIds = [];
});
console.log("  Enriched "+a2l.length+" A2 lessons");

console.log("\n=== STEP 3: Enrich A2 Grammar ===\n");
const a2g = d.grammar.A2;
a2g.forEach(q=>{
  q.skillType = "grammar";
  const topic = q.topic || q.unit || "";
  q.conceptId = q.conceptId || g2l.concept[topic] || g2l.concept["A2 Mix"] || "a2.mix.review";
  const lsns = g2l.lesson[topic] || ["A2_lesson_25"];
  if(!q.taughtInLessonId) q.taughtInLessonId = lsns[0] || q.lessonId || "A2_lesson_25";
  if(!q.difficulty){
    const t = topic.toLowerCase();
    if(["negation","pronomen","possessivartikel","imperativ","interrogatives","dativ artikel","dative"].some(x=>t.includes(x))) q.difficulty="easy";
    else if(["perfekt mit sein","partizip ii irregular","trennbare","subordinate clauses","two-way","wechselpräpositionen","präteritum","genitiv","nebensätze","dativpräpositionen","satzstellung","word order","a2 abschluss"].some(x=>t.includes(x))) q.difficulty="hard";
    else q.difficulty="medium";
  }
  if(!q.prerequisiteConceptIds) q.prerequisiteConceptIds = g2l.prereq[topic] || [];
});
console.log("  Grammar enriched: "+a2g.length+" items");

console.log("\n=== STEP 4: Enrich Reading/Listening/Writing/Speaking ===\n");
function cMap(x){
  const s=(x.title+" "+(x.text||x.script||x.prompt||"")).toLowerCase();
  for(const e of kwMap)for(const k of e.k)if(s.includes(k))return e.l;
  return "A2_lesson_25";
}
let rC=0;d.reading.A2.forEach(x=>{if(!x.taughtInLessonId){x.taughtInLessonId=cMap(x);rC++;}});
console.log("  Reading taughtInLessonId: "+rC+"/"+d.reading.A2.length);
let lC=0;d.listening.A2.forEach(x=>{if(!x.taughtInLessonId){x.taughtInLessonId=cMap(x);lC++;}});
console.log("  Listening taughtInLessonId: "+lC+"/"+d.listening.A2.length);
let wC=0;d.writing.A2.forEach(x=>{if(!x.taughtInLessonId){x.taughtInLessonId=cMap(x);wC++;}if(!x.rubric){x.rubric=wrRb.map(r=>({criterion:r.criterion,description:r.description,points:r.points}));}if(!x.rubricKeys){x.rubricKeys=wrRb.map(r=>r.key);}});
console.log("  Writing taughtInLessonId: "+wC+"/"+d.writing.A2.length+" rubric: "+d.writing.A2.filter(x=>x.rubric).length);
let sC=0;d.speaking.A2.forEach(x=>{if(!x.taughtInLessonId){x.taughtInLessonId=cMap(x);sC++;}if(!x.rubric){x.rubric=spRb.map(r=>({criterion:r.criterion,description:r.description,points:r.points}));}if(!x.rubricKeys){x.rubricKeys=spRb.map(r=>r.key);}});
console.log("  Speaking taughtInLessonId: "+sC+"/"+d.speaking.A2.length+" rubric: "+d.speaking.A2.filter(x=>x.rubric).length);

console.log("\n=== STEP 5: Link Grammar Questions to Lessons ===\n");
a2l.forEach(l=>{
  l.linkedQuestionIds = d.grammar.A2.filter(q=>q.taughtInLessonId===l.id).map(q=>q.id);
});
const totalLinks = a2l.reduce((s,l)=>s+l.linkedQuestionIds.length,0);
console.log("  Total links: "+totalLinks);

